export async function POST(req: Request) {
  const { notes } = await req.json()
  const stream = ai.messages.stream(
    { model, max_tokens: 400, system: SUMMARY_SYSTEM, messages: [{ role: "user", content: notes }] },
    { signal: req.signal },                          // tab closed -> stop paying
  )
  const body = new ReadableStream({
    async start(c) {
      stream.on("text", (t) => c.enqueue(new TextEncoder().encode(t)))
      logUsage(model, (await stream.finalMessage()).usage)  // usage arrives at the end
      c.close()
    },
  })
  return new Response(body, { headers: { "Content-Type": "text/plain; charset=utf-8" } })
}

