async function save(contact) {
  try {
    const res = await fetch("/api/contacts", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ id, ...contact }),   // server ignores an id it already has
      signal: AbortSignal.timeout(10_000),        // give up after 10s, no endless spinner
    });
