async function callWithRetry(fn, { tries = 3, base = 300 } = {}) {
  for (let i = 0; ; i++) {
    try {
      return await fn(AbortSignal.timeout(5000));      // deadline: 5s
    } catch (e) {
      const retryable = e.name === "TimeoutError" || e.status >= 500 || e.status === 429;
      if (!retryable || i === tries - 1) throw e;
      const wait = base * 2 ** i + Math.random() * 100;  // 300, 600, 1200 (+jitter)
      await sleep(wait);                                  // your own delay helper
    }
  }
}
