async function getProduct(id) {
  const key = `product:v2:${id}`            // key: only what changes the answer
  try {
    const hit = await redis.get(key)
    if (hit) return JSON.parse(hit)         // HIT - skip the work
  } catch { /* redis down -> fall through */ }

  const row = await db.product.find(id)     // MISS - do the work
  try { await redis.set(key, JSON.stringify(row), 'EX', 300) } catch {}
  return row                                 // TTL: trusted for 300s
}

