const PRICES = { in: Number(process.env.AI_PRICE_IN), out: Number(process.env.AI_PRICE_OUT) }

export async function POST(req: Request) {
  const { text } = await req.json()
  const res = await ai.messages.create({
    model: process.env.AI_MODEL!,
    max_tokens: 400,                          // cap the answer
    messages: [{ role: "user", content: text }],
  }, { timeout: 20_000 })                     // never wait forever
  const u = res.usage
  const cost = (u.input_tokens * PRICES.in + u.output_tokens * PRICES.out) / 1_000_000
  console.log(JSON.stringify({ event: "ai_call", in: u.input_tokens, out: u.output_tokens, cost }))
  const out = res.content.find((b) => b.type === "text")
  return Response.json({ text: out?.text ?? "" })
}

